<?php require_once '../includes/db.php';require_once '../includes/functions.php';admin_required();if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();$id=(int)$_POST['id'];$s=$conn->prepare("UPDATE products SET active=0 WHERE id=?");$s->bind_param('i',$id);$s->execute();flash('Product hidden from the storefront.');header('Location: products.php');exit;}$q=trim($_GET['q']??'');if($q){$like="%$q%";$s=$conn->prepare("SELECT * FROM products WHERE name LIKE ? OR category LIKE ? ORDER BY id DESC");$s->bind_param('ss',$like,$like);$s->execute();$products=$s->get_result()->fetch_all(MYSQLI_ASSOC);}else $products=$conn->query("SELECT * FROM products ORDER BY id DESC")->fetch_all(MYSQLI_ASSOC);$title='Products';$adminPage=true;include '../includes/header.php';?><div class="heading"><div><small>CATALOGUE</small><h2>Products</h2><p>Add, edit, search or hide products.</p></div><a class="btn dark" href="product_form.php">＋ Add product</a></div><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="Search name/category"><button class="btn">Search</button></form><div class="panel scroll"><table><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Visibility</th><th>Actions</th></tr><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['category'])?></td><td>₹<?=number_format($p['price'],2)?></td><td><?=$p['stock']?></td><td><?=$p['active']?'Active':'Hidden'?></td><td><a href="product_form.php?id=<?=$p['id']?>">Edit</a> <?php if($p['active']):?><form class="inline" method="post" data-confirm="Hide this product?"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="link danger">Hide</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php include '../includes/footer.php';?>